class BridgeSourceCapabilities {
  /// The same agent token [`BridgeLaneCapabilities::kind`] carries.
  final String kind;
  final bool create;
  final bool createOptions;

  const BridgeSourceCapabilities({
    required this.kind,
    required this.create,
    required this.createOptions,
  });

  @override
