  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeSourceCapabilities &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          create == other.create &&
          createOptions == other.createOptions;
}

